async function syncIdeaRelays(){if(!token()||!window.BDVault?.status?.().unlocked)return;const x=await cloud('/capture-transfer/inbox');for(const row of (x.relays||[]).slice(0,30)){try{const pair=await vault('/capture-access-pair?id='+encodeURIComponent(row.pairId)),pull=await cloud('/capture-transfer/pull?relay='+encodeURIComponent(row.relay));if(!['received','chunked'].includes(pull.status))continue;const ciphertext=await relayCiphertext(row.relay,pull),payload=await decryptRelay(ciphertext,pair.pair.secret);if(payload?.domain!=='knowledge'&&!['idea','method'].includes(payload?.captureType))continue;await storeLocalIdea(payload);await postCloud('/capture-transfer/ack',{relay:row.relay});if(payload.captureType==='method')window.dispatchEvent(new Event('bd-method-received'))}catch(err){console.warn('knowledge relay',err)}}}
async function storeLocalIdea(payload){const raw=new TextEncoder().encode(JSON.stringify(payload)),pages=Array.isArray(payload.inkPages)?payload.inkPages.some(p=>(p.strokes||[]).length):false,method=payload.captureType==='method';return vault('/knowledge-idea-inbox',{method:'POST',body:{captureId:payload.captureId,contentKind:method?'method':'idea',captureType:payload.knowledgeCaptureType||'',title:payload.label||'',body:payload.noteText||'',sourceType:method?payload.methodSourceType||'':payload.ideaSourceType||'own',sourceDescription:method?payload.methodSourceDescription||'':'',sourceUrl:method?payload.methodSourceUrl||'':payload.ideaSourceUrl||'',hasAudio:(payload.audio||[]).length>0,hasInk:pages,hasText:!!String(payload.noteText||'').trim(),hasPhotos:(payload.photos||[]).length>0,rawBase64:bytes64(raw),createdAt:payload.createdAt}})}
