function captureTypeShort(rec){const t=String(rec?.captureType||'').toLowerCase();if(t==='audio')return'Audio';if(['image','screenshot'].includes(t))return'Bild';if(['link','web'].includes(t))return'Web';if(t==='handwriting')return'Handschrift';return'Text'}
function senseIconForCapture(rec){const t=String(rec?.captureType||'').toLowerCase(),s=String(rec?.sourceType||'').toLowerCase();if(['image','screenshot'].includes(t))return'i-source-image';if(t==='audio')return'i-format-podcast';if(['link','web'].includes(t))return'i-source-web';if(s==='youtube')return'i-source-video';if(s==='reddit')return'i-source-forum';if(['book','paper'].includes(s))return'i-source-file';return'i-source-own'}
function senseSourceSummary(captures){const counts={};for(const c of captures||[]){const k=captureTypeShort(c);counts[k]=(counts[k]||0)+1}return Object.entries(counts).map(([k,v])=>`${v} ${k}`).join(' · ')}
function renderSenseOverview(){const host=$('#senseOverview');if(!host)return;const o=senseOverview||{};host.innerHTML=`<div class="sense-stat"><strong>${Number(o.newCaptures||0)}</strong><span>neue Captures</span></div><div class="sense-stat"><strong>${Number(o.topicSuggestions||0)}</strong><span>Themenvorschläge</span></div><div class="sense-stat"><strong>${Number(o.possibleConcepts||0)}</strong><span>mögliche Concepts</span></div><div class="sense-stat"><strong>${Number(o.unclearCaptures||0)}</strong><span>noch unklar</span></div>`;const call=$('#senseSessionCallout'),bar=$('#activeSessionBar');if(call)call.hidden=!!senseSession;if(bar)bar.hidden=!senseSession;if(senseSession&&$('#activeSessionLabel'))$('#activeSessionLabel').textContent=`Gestartet ${fmt(senseSession.startedAt)} · ${senseSession.clusters?.length||0} Themenvorschläge`}
function renderSenseClusters(){const host=$('#senseClusters');if(!host)return;if(!senseSession){host.innerHTML='<div class="kh-empty">Starte eine Content Session, um verdichtete Themenvorschläge zu sehen.</div>';return}const rows=senseSession.clusters||[];host.innerHTML=rows.length?rows.map(c=>{const ai=c.aiState||'pending',state=ai==='done'?'lokal analysiert':ai==='processing'?'KI analysiert …':ai==='waiting'?'Wartet auf lokale KI':ai==='error'?'KI-Prüfung nötig':'KI vorbereitet';return `<article class="sense-cluster-card" data-sense-cluster="${esc(c.id)}"><div class="sense-card-top"><span class="sense-capture-count">${c.captureIds?.length||0} Captures</span><span class="kh-pill ${ai==='waiting'||ai==='error'?'warn':''}">${esc(state)}</span></div><h4>${esc(c.title||'Themenvorschlag')}</h4><p>${esc(c.summary||'Die lokale Ähnlichkeitsanalyse hat hier einen möglichen Zusammenhang gefunden.')}</p><div class="sense-source-summary">${esc(senseSourceSummary(c.captures||[]))}</div>${(c.olderCaptureIds||[]).length?`<div class="sense-older-note">＋ ${(c.olderCaptureIds||[]).length} passendes ältere${(c.olderCaptureIds||[]).length===1?'s':''} Capture${(c.olderCaptureIds||[]).length===1?'':'s'}</div>`:''}<button class="kh-soft sense-open-cluster" type="button">Öffnen</button></article>`}).join(''):'<div class="kh-empty">Keine sinnvollen Mehrfach-Zusammenhänge gefunden. Einzelgänger bleiben bewusst erlaubt.</div>';host.querySelectorAll('[data-sense-cluster]').forEach(card=>card.onclick=e=>{if(e.target.closest('button')||e.currentTarget===e.target)openSenseCluster(card.dataset.senseCluster);else openSenseCluster(card.dataset.senseCluster)})}
function senseCaptureCard(rec,{older=false,removable=false}={}){return `<article class="sense-capture-card" data-sense-capture="${esc(rec.id)}">${removable?`<label class="sense-split-check" title="Für Abtrennung markieren"><input type="checkbox" data-sense-split="${esc(rec.id)}"></label>`:''}<div class="sense-capture-icon">${svgIcon(senseIconForCapture(rec))}</div><div class="sense-capture-main"><div class="sense-capture-title"><strong>${esc(rec.title||'Capture')}</strong>${rec.reviewStatus==='unseen'?'<span class="new-dot">neu</span>':''}</div><p>${esc((rec.summary||'').slice(0,260))}</p><span class="kh-muted">${esc(captureTypeShort(rec))} · ${esc(fmt(rec.receivedAt))}${older?' · älteres Material':''}</span></div><div class="sense-capture-actions"><button class="kh-soft" data-sense-action="open" type="button">Original</button>${older?'<button class="kh-soft" data-sense-action="add" type="button">＋ Quelle</button>':removable?'<button class="kh-soft" data-sense-action="remove" type="button">Entfernen</button>':''}<button class="kh-soft" data-sense-action="reviewed" type="button">Gesehen</button><button class="kh-soft" data-sense-action="parked" type="button">Parken</button></div></article>`}
function renderSenseOutliers(){const host=$('#senseOutliers');if(!host)return;const rows=senseSession?.outliers||[];host.innerHTML=rows.length?rows.slice(0,24).map(r=>senseCaptureCard(r)).join(''):'<div class="kh-empty compact">Keine unklaren Captures in dieser Session.</div>';bindSenseCaptureActions(host)}
function renderSenseConcepts(){const host=$('#senseConcepts');if(!host)return;host.innerHTML=senseConcepts.length?senseConcepts.map(c=>`<article class="sense-concept-card" data-sense-concept="${esc(c.id)}" role="button" tabindex="0"><div class="sense-card-top"><span class="source-chip source-chip-clean">${svgIcon('i-sparkle')}<span>Concept</span></span><span class="kh-muted">${esc(fmt(c.updatedAt))}</span></div><h4>${esc(c.title)}</h4><p>${esc((c.core||'').slice(0,300))}</p><div class="card-tag-row">${(c.tags||[]).slice(0,5).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="tag source-count">${c.captureIds?.length||0} Quellen</span></div></article>`).join(''):'<div class="kh-empty compact">Noch keine bestätigten Concepts. Sie entstehen erst durch deine Entscheidung in einer Content Session.</div>';host.querySelectorAll('[data-sense-concept]').forEach(card=>{card.onclick=()=>openLocalConcept(card.dataset.senseConcept);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')openLocalConcept(card.dataset.senseConcept)}})}
function renderSensemaking(){renderSenseOverview();renderSenseClusters();renderSenseOutliers();renderSenseConcepts();const pill=$('#senseAiState');if(pill){const pending=(senseSession?.clusters||[]).some(c=>['pending','processing','waiting'].includes(c.aiState));pill.textContent=pending?'Lokale KI arbeitet im Hintergrund':'Local First · bereit';pill.className='kh-pill '+(pending?'':'ok')}}
function scheduleSensePoll(){if(sensePollTimer){clearTimeout(sensePollTimer);sensePollTimer=null}if(!senseSession)return;const needs=(senseSession.clusters||[]).some(c=>['pending','processing','waiting'].includes(c.aiState));if(needs)sensePollTimer=setTimeout(()=>loadSensemaking(true).catch(()=>{}),3500)}
async function loadSensemaking(silent=false){try{await window.BDVault?.checkHealth?.();if(!window.BDVault?.status?.().unlocked){senseOverview=null;senseSession=null;const pill=$('#senseAiState');if(pill){pill.textContent='Wartet auf Entsperren des Local Vault';pill.className='kh-pill warn'};renderSensemaking();return}const [ov,session,concepts]=await Promise.all([vault('/knowledge/sensemaking/overview'),vault('/knowledge/sensemaking/session'),vault('/knowledge/concepts')]);senseOverview=ov.overview||{};senseSession=session.session||null;senseConcepts=concepts.concepts||[];renderSensemaking();scheduleSensePoll()}catch(err){const pill=$('#senseAiState');if(pill){pill.textContent='Sensemaking lokal nicht verfügbar';pill.className='kh-pill warn'};if(!silent)notice(err.message,'warn')}}
async function startSenseSession(){try{const x=await vault('/knowledge/sensemaking/session/start',{method:'POST',body:{}});senseSession=x.session;await vault('/knowledge/sensemaking/session/enrich',{method:'POST',body:{id:senseSession.id}}).catch(()=>{});await loadSensemaking(true);notice('Content Session gestartet. Die lokale KI verfeinert die Vorschläge im Hintergrund.')}catch(err){notice(err.message,'warn')}}
async function completeSenseSession(){if(!senseSession)return;try{const x=await vault('/knowledge/sensemaking/session/complete',{method:'POST',body:{id:senseSession.id}});const st=x.session?.stats||{};senseSession=null;await loadSensemaking(true);notice(`Content Session abgeschlossen · ${st.capturesReviewed||0} Captures geprüft · ${st.conceptsCreated||0} Concepts erstellt · ${st.parked||0} geparkt`)}catch(err){notice(err.message,'warn')}}
function renderSenseClusterDialog(){if(!activeSenseCluster)return;const c=activeSenseCluster;$('#senseClusterTitle').value=c.title||'';$('#senseClusterSummary').textContent=c.summary||'Die lokale Ähnlichkeitsanalyse hat hier einen möglichen Zusammenhang gefunden.';const state=c.aiState||'pending';$('#senseClusterAiState').textContent=state==='done'?'lokal analysiert':state==='processing'?'KI analysiert …':state==='waiting'?'Wartet auf lokale KI':state==='error'?'KI-Prüfung nötig':'vorbereitet';$('#senseClusterAiState').className='kh-pill '+(state==='waiting'||state==='error'?'warn':'');const members=(c.captures||[]).filter(r=>senseClusterDraftIds.includes(String(r.id)));$('#senseClusterCaptures').innerHTML=members.length?members.map(r=>senseCaptureCard(r,{removable:true})).join(''):'<div class="kh-empty compact">Keine Captures mehr in diesem Vorschlag.</div>';const older=(c.olderCaptures||[]).filter(r=>!senseClusterDraftIds.includes(String(r.id)));$('#senseOlderCaptures').innerHTML=older.length?older.slice(0,12).map(r=>senseCaptureCard(r,{older:true})).join(''):'<div class="kh-empty compact">Kein weiteres älteres Material vorgeschlagen.</div>';const merge=$('#senseMergeTarget');if(merge){merge.innerHTML='<option value="">Mit anderem Vorschlag zusammenführen …</option>'+((senseSession?.clusters||[]).filter(x=>x.id!==c.id).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join(''))}const box=$('#senseConceptSuggestions'),suggestions=c.conceptSuggestions||[];box.innerHTML=(suggestions.length?suggestions.slice(0,3).map((x,i)=>`<article class="concept-suggestion" data-concept-suggestion="${i}"><label>Titel<input data-concept-title value="${esc(x.title||'')}"></label><label>Kernidee<textarea data-concept-core rows="4">${esc(x.core||'')}</textarea></label><div class="concept-suggestion-actions"><button class="kh-primary" data-create-concept="${i}" type="button">Concept erstellen</button><button class="kh-soft" data-dismiss-concept="${i}" type="button">Nicht interessant</button></div></article>`).join(''):`<div class="kh-empty compact">${state==='waiting'?'Die Cluster-Struktur ist lokal vorhanden. Die sprachliche Concept-Analyse wartet auf LM Studio.':state==='processing'||state==='pending'?'Die lokale KI arbeitet noch an möglichen Blickwinkeln.':'Keine tragfähigen Concept-Vorschläge erzeugt – das ist völlig in Ordnung.'}</div>`)+`<article class="concept-suggestion manual" data-concept-suggestion="manual"><label>Titel<input data-concept-title value="${esc(c.title||'')}"></label><label>Kernidee<textarea data-concept-core rows="4" placeholder="Deine eigene Kernidee …"></textarea></label><button class="kh-soft" data-create-concept="manual" type="button">Eigenes Concept erstellen</button></article>`;bindSenseCaptureActions($('#senseClusterCaptures'));bindSenseCaptureActions($('#senseOlderCaptures'));box.querySelectorAll('[data-create-concept]').forEach(b=>b.onclick=()=>createConceptFromSuggestion(b.dataset.createConcept==='manual'?'manual':Number(b.dataset.createConcept)));box.querySelectorAll('[data-dismiss-concept]').forEach(b=>b.onclick=()=>dismissConceptSuggestion(Number(b.dataset.dismissConcept)))}
function openSenseCluster(id){activeSenseCluster=(senseSession?.clusters||[]).find(c=>String(c.id)===String(id));if(!activeSenseCluster)return;senseClusterDraftIds=(activeSenseCluster.captureIds||[]).map(String);renderSenseClusterDialog();$('#senseClusterDialog').showModal()}
async function openSenseCapture(id){if(!ideaInbox.some(x=>String(x.id)===String(id)))await loadIdeaInbox(false);openInbox(id)}
async function senseReviewCapture(id,status){try{await vault('/knowledge/capture/review',{method:'POST',body:{captureId:String(id),status,sessionId:senseSession?.id||''}});for(const c of [...(senseSession?.clusters||[]),...(senseSession?.outliers||[])]){if(c&&String(c.id)===String(id))c.reviewStatus=status;if(c?.captures)for(const r of c.captures)if(String(r.id)===String(id))r.reviewStatus=status;if(c?.olderCaptures)for(const r of c.olderCaptures)if(String(r.id)===String(id))r.reviewStatus=status}renderSensemaking();if(activeSenseCluster)renderSenseClusterDialog()}catch(err){notice(err.message,'warn')}}
function bindSenseCaptureActions(host){if(!host)return;host.querySelectorAll('[data-sense-capture]').forEach(card=>card.querySelectorAll('[data-sense-action]').forEach(btn=>btn.onclick=async e=>{e.stopPropagation();const id=card.dataset.senseCapture,act=btn.dataset.senseAction;if(act==='open')return openSenseCapture(id);if(act==='remove'){senseClusterDraftIds=senseClusterDraftIds.filter(x=>String(x)!==String(id));return renderSenseClusterDialog()}if(act==='add'){if(!senseClusterDraftIds.includes(String(id)))senseClusterDraftIds.push(String(id));return renderSenseClusterDialog()}if(act==='reviewed'||act==='parked')return senseReviewCapture(id,act)}))}
async function saveSenseCluster(){if(!activeSenseCluster||!senseSession)return;try{const x=await vault('/knowledge/sensemaking/cluster/update',{method:'POST',body:{id:activeSenseCluster.id,sessionId:senseSession.id,title:$('#senseClusterTitle').value.trim(),captureIds:senseClusterDraftIds,status:'edited'}});activeSenseCluster=x.cluster;await loadSensemaking(true);activeSenseCluster=(senseSession?.clusters||[]).find(c=>c.id===x.cluster.id)||x.cluster;senseClusterDraftIds=(activeSenseCluster.captureIds||[]).map(String);renderSenseClusterDialog();notice('Themenvorschlag angepasst. Deine Änderung bleibt auf diese Session beschränkt.')}catch(err){notice(err.message,'warn')}}
async function ignoreSenseCluster(){if(!activeSenseCluster||!senseSession)return;try{await vault('/knowledge/sensemaking/cluster/update',{method:'POST',body:{id:activeSenseCluster.id,sessionId:senseSession.id,status:'ignored'}});$('#senseClusterDialog').close();activeSenseCluster=null;await loadSensemaking(true);notice('Vorschlag ignoriert. Die Captures selbst bleiben unverändert erhalten.')}catch(err){notice(err.message,'warn')}}
async function dismissConceptSuggestion(index){if(!activeSenseCluster||!senseSession)return;const suggestions=[...(activeSenseCluster.conceptSuggestions||[])];suggestions.splice(index,1);try{const x=await vault('/knowledge/sensemaking/cluster/update',{method:'POST',body:{id:activeSenseCluster.id,sessionId:senseSession.id,conceptSuggestions:suggestions,status:activeSenseCluster.status||'edited'}});activeSenseCluster=x.cluster;await loadSensemaking(true);activeSenseCluster=(senseSession?.clusters||[]).find(c=>c.id===x.cluster.id)||x.cluster;senseClusterDraftIds=(activeSenseCluster.captureIds||[]).map(String);renderSenseClusterDialog()}catch(err){notice(err.message,'warn')}}
async function moveSenseCaptures(){if(!activeSenseCluster||!senseSession)return;const marked=$$('#senseClusterCaptures [data-sense-split]:checked').map(x=>String(x.dataset.senseSplit)),targetId=$('#senseMergeTarget')?.value;if(!marked.length){notice('Markiere mindestens einen Capture zum Verschieben.','warn');return}if(!targetId){notice('Wähle den Ziel-Themenvorschlag aus.','warn');return}const target=(senseSession.clusters||[]).find(c=>c.id===targetId);if(!target)return;const targetIds=[...(target.captureIds||[])];for(const id of marked)if(!targetIds.includes(id))targetIds.push(id);const remain=senseClusterDraftIds.filter(id=>!marked.includes(id));if(!remain.length){notice('Der ursprüngliche Vorschlag darf nicht leer werden. Nutze sonst „Zusammenführen“.','warn');return}try{await vault('/knowledge/sensemaking/cluster/update',{method:'POST',body:{id:target.id,sessionId:senseSession.id,captureIds:targetIds,status:'edited'}});await vault('/knowledge/sensemaking/cluster/update',{method:'POST',body:{id:activeSenseCluster.id,sessionId:senseSession.id,captureIds:remain,status:'edited'}});$('#senseClusterDialog').close();await loadSensemaking(true);notice('Markierte Captures in einen anderen Vorschlag verschoben. Die Originale bleiben unverändert.')}catch(err){notice(err.message,'warn')}}
async function splitSenseCluster(){if(!activeSenseCluster||!senseSession)return;const marked=$$('#senseClusterCaptures [data-sense-split]:checked').map(x=>String(x.dataset.senseSplit));if(marked.length<2){notice('Markiere mindestens zwei Captures für einen neuen Vorschlag.','warn');return}if(marked.length>=senseClusterDraftIds.length){notice('Mindestens ein Capture muss im ursprünglichen Vorschlag verbleiben.','warn');return}const title=prompt('Name des neuen Themenvorschlags:','Neuer Zusammenhang');if(!title)return;try{await vault('/knowledge/sensemaking/cluster/create',{method:'POST',body:{sessionId:senseSession.id,title,captureIds:marked}});senseClusterDraftIds=senseClusterDraftIds.filter(id=>!marked.includes(id));await vault('/knowledge/sensemaking/cluster/update',{method:'POST',body:{id:activeSenseCluster.id,sessionId:senseSession.id,captureIds:senseClusterDraftIds,status:'edited'}});$('#senseClusterDialog').close();await loadSensemaking(true);notice('Themenvorschlag aufgeteilt. Beide Gruppen bleiben Session-Vorschläge, keine Ordner.')}catch(err){notice(err.message,'warn')}}
async function mergeSenseCluster(){if(!activeSenseCluster||!senseSession)return;const target=$('#senseMergeTarget')?.value;if(!target){notice('Bitte zuerst einen zweiten Themenvorschlag auswählen.','warn');return}try{await vault('/knowledge/sensemaking/cluster/merge',{method:'POST',body:{sessionId:senseSession.id,sourceId:activeSenseCluster.id,targetId:target}});$('#senseClusterDialog').close();activeSenseCluster=null;await loadSensemaking(true);notice('Themenvorschläge zusammengeführt. Die Captures selbst wurden nicht verschoben oder kopiert.')}catch(err){notice(err.message,'warn')}}

function localConceptCaptureCard(rec,mode='source'){const action=mode==='source'?'remove':'add';return `<article class="sense-capture-card local-concept-capture" data-local-capture="${esc(rec.id)}"><div class="sense-capture-icon">${svgIcon(senseIconForCapture(rec))}</div><div class="sense-capture-main"><strong>${esc(rec.title||'Capture')}</strong><p>${esc((rec.summary||'').slice(0,240))}</p><span class="kh-muted">${esc(captureTypeShort(rec))} · ${esc(fmt(rec.receivedAt))}${rec.similarity?` · Ähnlichkeit ${Math.round(Number(rec.similarity)*100)} %`:''}</span></div><div class="sense-capture-actions"><button class="kh-soft" data-local-action="open" type="button">Original</button><button class="kh-soft" data-local-action="${action}" type="button">${action==='add'?'+ Quelle':'Entfernen'}</button></div></article>`}
function bindLocalConceptCaptureActions(host){if(!host)return;host.querySelectorAll('[data-local-capture]').forEach(card=>card.querySelectorAll('[data-local-action]').forEach(btn=>btn.onclick=async()=>{const id=card.dataset.localCapture,act=btn.dataset.localAction;if(act==='open')return openSenseCapture(id);if(!activeLocalConcept)return;try{const x=await vault('/knowledge/concept/link',{method:'POST',body:{conceptId:activeLocalConcept.id,captureId:id,action:act==='remove'?'remove':'add'}});activeLocalConcept=x.concept;await refreshLocalConceptRelated();renderLocalConcept();await loadSensemaking(true);notice(act==='remove'?'Quelle aus Concept entfernt. Original bleibt erhalten.':'Capture als Quelle hinzugefügt.')}catch(err){notice(err.message,'warn')}}))}
async function refreshLocalConceptRelated(){if(!activeLocalConcept)return;try{const x=await vault('/knowledge/concept/related?id='+encodeURIComponent(activeLocalConcept.id));activeLocalConcept._related=x.items||[]}catch(_){activeLocalConcept._related=[]}}
function renderLocalConcept(){if(!activeLocalConcept)return;const c=activeLocalConcept;$('#localConceptHeading').textContent=c.title||'Concept';$('#localConceptTitle').value=c.title||'';$('#localConceptCore').value=c.core||'';$('#localConceptTags').value=(c.tags||[]).join(', ');$('#localConceptNotes').value=c.notes||'';$('#localConceptArchive').textContent=c.status==='archived'?'Wiederherstellen':'Archivieren';const sources=$('#localConceptSources');sources.innerHTML=(c.captures||[]).length?(c.captures||[]).map(r=>localConceptCaptureCard(r,'source')).join(''):'<div class="kh-empty compact">Noch keine Quellen verknüpft.</div>';bindLocalConceptCaptureActions(sources);const related=$('#localConceptRelated');related.innerHTML=(c._related||[]).length?(c._related||[]).map(r=>localConceptCaptureCard(r,'related')).join(''):'<div class="kh-empty compact">Aktuell keine weiteren starken Ähnlichkeitsvorschläge.</div>';bindLocalConceptCaptureActions(related);const tl=$('#localConceptTimeline');tl.innerHTML=(c.timeline||[]).length?(c.timeline||[]).map(e=>`<div class="timeline-event"><div class="timeline-dot"></div><time>${esc(new Intl.DateTimeFormat('de-AT',{dateStyle:'medium',timeStyle:'short'}).format(new Date(e.at)))}</time><div><strong>${esc(({concept_created:'Concept erstellt',concept_updated:'Concept bearbeitet',capture_added:'Capture hinzugefügt',capture_removed:'Capture entfernt'}[e.type]||e.type))}</strong>${e.detail?`<span>${esc(e.detail)}</span>`:''}</div></div>`).join(''):'<div class="kh-empty compact">Noch keine Timeline-Einträge.</div>'}
async function openLocalConcept(id){try{const x=await vault('/knowledge/concept?id='+encodeURIComponent(id));activeLocalConcept=x.concept;const cb=$('#localConceptCommentBtn');if(cb){cb.dataset.commentType='concept';cb.dataset.commentId=String(activeLocalConcept.id||'');cb.dataset.commentTitle=activeLocalConcept.title||'Concept'}await refreshLocalConceptRelated();renderLocalConcept();$('#localConceptSearchResults').innerHTML='';$('#localConceptSearchInput').value='';$('#localConceptDialog').showModal()}catch(err){notice(err.message,'warn')}}
async function saveLocalConcept(){if(!activeLocalConcept)return;try{const x=await vault('/knowledge/concept/update',{method:'POST',body:{id:activeLocalConcept.id,title:$('#localConceptTitle').value.trim(),core:$('#localConceptCore').value.trim(),tags:uniqueTags($('#localConceptTags').value.split(',')),notes:$('#localConceptNotes').value}});activeLocalConcept=x.concept;await refreshLocalConceptRelated();renderLocalConcept();await loadSensemaking(true);notice('Concept gespeichert.')}catch(err){notice(err.message,'warn')}}
async function archiveLocalConcept(){if(!activeLocalConcept)return;const status=activeLocalConcept.status==='archived'?'concept':'archived';try{const x=await vault('/knowledge/concept/update',{method:'POST',body:{id:activeLocalConcept.id,status}});activeLocalConcept=x.concept;if(status==='archived')$('#localConceptDialog').close();else renderLocalConcept();await loadSensemaking(true);notice(status==='archived'?'Concept archiviert.':'Concept wiederhergestellt.')}catch(err){notice(err.message,'warn')}}
async function searchLocalConceptCaptures(){if(!activeLocalConcept)return;const q=$('#localConceptSearchInput').value.trim(),host=$('#localConceptSearchResults');if(q.length<2){host.innerHTML='<div class="kh-empty compact">Mindestens zwei Zeichen eingeben.</div>';return}try{const x=await vault('/knowledge/captures/search?q='+encodeURIComponent(q)+'&limit=25'),linked=new Set(activeLocalConcept.captureIds||[]),rows=(x.items||[]).filter(r=>!linked.has(String(r.id)));host.innerHTML=rows.length?rows.map(r=>localConceptCaptureCard(r,'related')).join(''):'<div class="kh-empty compact">Keine weiteren Captures gefunden.</div>';bindLocalConceptCaptureActions(host)}catch(err){notice(err.message,'warn')}}
async function createConceptFromSuggestion(index){if(!activeSenseCluster||!senseSession)return;const card=$(`[data-concept-suggestion="${index}"]`),title=card?.querySelector('[data-concept-title]')?.value.trim()||'',core=card?.querySelector('[data-concept-core]')?.value.trim()||'';if(!title){notice('Bitte einen Concept-Titel eingeben.','warn');return}const tags=uniqueTags((activeSenseCluster.captures||[]).filter(r=>senseClusterDraftIds.includes(String(r.id))).flatMap(r=>[...(r.topics||[]),...(r.tags||[])])).slice(0,12);try{await vault('/knowledge/concept/create',{method:'POST',body:{title,core,captureIds:senseClusterDraftIds,tags,clusterId:activeSenseCluster.id,origin:{sessionId:senseSession.id,clusterId:activeSenseCluster.id,source:'local-sensemaking'}}});await loadSensemaking(true);$('#senseClusterDialog').close();notice('Concept erstellt. Die ursprünglichen Captures bleiben als eigenständige Quellen erhalten.')}catch(err){notice(err.message,'warn')}}
